UPDATE documents
SET title = 'Постановление Правительства РФ от 21 ноября 2023 года № 1944 – запрет продажи отдельных маркированных товаров',
    area = 'Запрет продажи отдельных маркированных товаров',
    product_group = 'Продажа и кассовый контроль в Российской Федерации',
    keywords = '№ 1944; запрет продажи маркированных товаров; запрет оборота отдельных товаров; ГИС МТ; государственная информационная система мониторинга; отсутствие сведений о товаре; кассовая проверка; правила применения запрета продажи; реализация маркированных товаров; Российская Федерация',
    description = 'Постановление утверждает перечень случаев, в которых продажа товаров, подлежащих обязательной маркировке, запрещается на основании сведений либо отсутствия необходимых сведений в государственной информационной системе мониторинга за оборотом товаров (ГИС МТ), а также правила применения такого запрета и особенности его внедрения для отдельных товаров. Это акт о запрете продажи, а не полный порядок маркировки каждой товарной группы. Проверяйте действующую редакцию и специальные правила конкретной категории.',
    content = 'ПРЕДМЕТ РЕГУЛИРОВАНИЯ\nПостановление Правительства РФ от 21.11.2023 № 1944 утверждает перечень случаев, когда продажа товаров, подлежащих обязательной маркировке средствами идентификации, запрещена на основании информации в государственной информационной системе мониторинга за оборотом товаров (ГИС МТ) либо отсутствия в системе необходимой информации о таких товарах.\n\nЧТО РЕГУЛИРУЕТ\n1. Случаи запрета продажи отдельных маркируемых товаров по результатам проверки сведений ГИС МТ.\n2. Особенности внедрения запрета в отношении отдельных товаров.\n3. Правила применения запрета продажи и получения информации из ГИС МТ.\n\nЧЕГО НЕ ЗАМЕНЯЕТ\nПостановление № 1944 не является полным порядком обязательной маркировки всех товаров, не устанавливает универсальный перечень всех маркируемых категорий и не заменяет специальные правила маркировки каждой товарной группы. Для определения обязанности маркировать товар и сроков следует отдельно проверять применимые акты и код товара.\n\nИСТОЧНИК\nОфициальное опубликование: https://publication.pravo.gov.ru/document/0001202311270058. Редакцию, изменения и применимость к конкретной категории необходимо сверять по официальному тексту на дату операции.',
    updated_by = 'legal-source-quality-review',
    updated_at = NOW(),
    version_number = version_number + 1
WHERE id = 'a1000000-0000-4000-8000-000000000013';

UPDATE documents
SET title = 'Постановление Кабинета Министров КР от 1 июля 2025 года № 385 – учетно-контрольные марки для отдельных категорий товаров',
    area = 'Учетно-контрольные марки',
    product_group = 'Бутилированная и упакованная вода – ТН ВЭД 2201',
    keywords = '№ 385; № 575; № 393; № 639; учетно-контрольные марки; вода бутилированная; вода упакованная; минеральная вода; газированная вода; ТН ВЭД 2201; исключение лёд; 1 января 2026; 1 июля 2026; запрет оборота немаркированных остатков',
    description = 'Постановление № 385 утверждает Положение о порядке выдачи и применения учетно-контрольных марок в КР. По состоянию на редакцию, связанную с постановлением КМ КР от 25.09.2026 № 639, обязательная УKM-маркировка относится к бутилированной или упакованной воде, включая минеральную и газированную, кода ТН ВЭД 2201, за исключением льда: с 01.01.2026; оборот немаркированных остатков такой воды запрещён с 01.07.2026. Это не следует переносить на все товары или на обычные коды DataMatrix. Статус записи требует юридической проверки.',
    content = 'ПРЕДМЕТ РЕГУЛИРОВАНИЯ\nПостановление Кабинета Министров КР от 01.07.2025 № 385 «О введении учетно-контрольных марок в Кыргызской Республике» утверждает Положение о порядке выдачи и применения учетно-контрольных марок. Учетно-контрольная марка – отдельный вид маркировочного средства; её нельзя автоматически приравнивать к коду DataMatrix.\n\nАКТУАЛЬНАЯ СВЯЗАННАЯ РЕДАКЦИЯ\nПункт 2 постановления № 385 изложен в новой редакции постановлением Кабинета Министров КР от 25.09.2026 № 639. В новой редакции:\n1. С 01.01.2026 обязательной учетно-контрольной маркировке подлежит бутилированная или упакованная вода, в том числе минеральная и газированная, классифицируемая кодом ТН ВЭД 2201, за исключением льда.\n2. С 01.07.2026 запрещается оборот немаркированных учетно-контрольными марками остатков такой воды, также за исключением льда.\n\nГРАНИЦЫ ПРИМЕНЕНИЯ\nНе утверждать, что постановление № 385 вводит учетно-контрольные марки для всех товаров. Указанные требования касаются именно воды под кодом ТН ВЭД 2201 с приведённым исключением. Не смешивать учетно-контрольные марки с DataMatrix и внутренней/внешней маркировкой МЗКМ.\n\nПЕРВОИСТОЧНИКИ\nОфициальная страница постановления № 385: https://www.gov.kg/ru/npa/s/4687. Официальная запись Минюста по постановлению № 639, внёсшему изменение в пункт 2 постановления № 385: https://cbd.minjust.gov.kg/7-58349/edition/59440/ru. Перед практическим применением следует сверить текст обеих действующих редакций.',
    updated_by = 'legal-source-quality-review',
    updated_at = NOW(),
    version_number = version_number + 1
WHERE id = 'a1000000-0000-4000-8000-000000000004';

UPDATE documents
SET title = 'Соглашение ЕАЭС о маркировке товаров средствами идентификации от 2 февраля 2018 года – рамочные правила',
    area = 'Рамочное регулирование ЕАЭС',
    keywords = 'ЕАЭС; Соглашение о маркировке; 02.02.2018; 29.03.2019; рамочное соглашение; решения Совета ЕЭК; отдельные товарные категории; сроки маркировки; остатки; средства идентификации; структура информации',
    source_url = 'https://docs.eaeunion.org/documents/236/3485/',
    description = 'Рамочное Соглашение ЕАЭС о маркировке товаров средствами идентификации заключено 02.02.2018 и вступило в силу 29.03.2019. Оно задаёт наднациональную основу согласованной маркировки. Конкретные параметры для отдельных товарных категорий устанавливаются отдельными решениями Совета ЕЭК; само рамочное соглашение не задаёт универсальные сроки и порядок маркировки каждой группы.',
    content = 'ПРЕДМЕТ И ДАТЫ\nСоглашение о маркировке товаров средствами идентификации в Евразийском экономическом союзе заключено в Алматы 02.02.2018 и вступило в силу 29.03.2019. Соглашение имеет рамочный характер и входит в право ЕАЭС.\n\nЧТО ОНО УСТАНАВЛИВАЕТ\nСоглашение задаёт общую основу согласованной политики маркировки средствами идентификации и взаимодействия государств-членов.\n\nЧТО ОПРЕДЕЛЯЕТСЯ ОТДЕЛЬНО\nВ отношении каждой отдельной категории товаров отдельными решениями Совета Евразийской экономической комиссии устанавливаются конкретные параметры, в том числе дата введения маркировки, необходимость маркировки остатков, вид и характеристики средства идентификации, состав сведений о товаре, перечень товаров по ТН ВЭД и порядок маркировки.\n\nВАЖНО\nНе выводить из одного рамочного соглашения единый срок обязательной маркировки для всех товаров. Разделять наднациональную рамку ЕАЭС и отдельные решения по конкретным категориям, а также национальные процедуры государств-членов.\n\nОФИЦИАЛЬНЫЕ ИСТОЧНИКИ\nОфициальная правовая база ЕАЭС: https://docs.eaeunion.org/documents/236/3485/. Разъяснение ЕЭК о рамочном характере соглашения и отдельных решениях по категориям: https://eec.eaeunion.org/upload/medialibrary/66c/43.-TSifrovaya-markirovka-tovarov.pdf.',
    updated_by = 'legal-source-quality-review',
    updated_at = NOW(),
    version_number = version_number + 1
WHERE id = 'a1000000-0000-4000-8000-000000000007';

UPDATE documents
SET description = 'Постановление № 570 утверждает общие правила и перечни отдельных товаров для обязательной маркировки в КР. Наличие общих процедур не доказывает, что вся косметическая продукция без исключений подлежит маркировке: необходимо сверять точную товарную категорию, код ТН ВЭД, соответствующие приложения и последующие изменения. Запись находится на юридической проверке.',
    content = 'ПРЕДМЕТ\nПостановление Кабинета Министров КР от 18.10.2022 № 570 утверждает Положение о маркировке отдельных товаров в Кыргызской Республике и связанные перечни.\n\nПРОВЕРКА ТОВАРНОЙ ГРУППЫ\nОбщие правила не означают, что все виды продукции из широкой бытовой категории автоматически подлежат обязательной маркировке. Для косметической продукции необходимо установить точное описание товара и полный код ТН ВЭД, а затем проверить включение конкретной позиции в применимые перечни и исключения в действующей редакции постановления № 570 и последующих изменений.\n\nОГРАНИЧЕНИЕ\nЭта карточка не подтверждает обязательную маркировку всей косметики. Не переносить российские правила на Кыргызскую Республику. Статус записи – «На проверке»; перед юридическим выводом нужен текст действующей редакции и соответствующего приложения.',
    updated_by = 'legal-source-quality-review',
    updated_at = NOW(),
    version_number = version_number + 1
WHERE id = 'a1000000-0000-4000-8000-000000000001';

