INSERT INTO documents (
    id, title, jurisdiction, kind, area, product_group, keywords, document_number,
    document_date, source_url, description, content, status, created_by, updated_by,
    created_at, updated_at, version_number
) VALUES (
    'a1000000-0000-4000-8000-000000000033',
    'Постановление Кабинета Министров КР от 25 сентября 2026 года № 639 – изменения в налоговом администрировании и пункт 2 постановления № 385',
    'KG',
    'Нормативный акт',
    'Изменения к постановлению № 385 об учетно-контрольных марках',
    'Бутилированная и упакованная вода – ТН ВЭД 2201',
    '№ 639; 25.09.2026; № 385; учетно-контрольные марки; вода; бутилированная вода; упакованная вода; ТН ВЭД 2201; исключение лёд; 1 января 2026; 1 июля 2026; запрет оборота немаркированных остатков',
    '№ 639',
    '2026-09-25',
    'https://cbd.minjust.gov.kg/7-58349/edition/59440/ru',
    'Постановление № 639 от 25.09.2026 изменяет пункт 2 постановления КМ КР № 385. Уточнённая сфера – бутилированная/упакованная вода кода ТН ВЭД 2201, за исключением льда; даты обязательной учетно-контрольной маркировки и запрета оборота немаркированных остатков установлены в тексте изменений. Запись требует юридической проверки.',
    'ИЗМЕНЕНИЕ ПОСТАНОВЛЕНИЯ № 385\nПункт 10 постановления Кабинета Министров КР от 25.09.2026 № 639 излагает пункт 2 постановления № 385 в новой редакции.\n\nСФЕРА И ДАТЫ\n1. С 01.01.2026 обязательной учетно-контрольной маркировке подлежит бутилированная или упакованная вода, включая минеральную и газированную, код ТН ВЭД 2201, за исключением льда.\n2. С 01.07.2026 запрещается оборот немаркированных учетно-контрольными марками остатков такой воды, за исключением льда.\n\nГРАНИЦЫ\nИзменение относится к учетно-контрольным маркам и конкретной категории воды. Его нельзя трактовать как правило обязательной маркировки любой косметики, игрушек или иных товаров и нельзя автоматически применять к кодам DataMatrix.\n\nОФИЦИАЛЬНЫЙ ИСТОЧНИК\nЦентрализованная база правовой информации Минюста КР, редакция постановления № 639 от 25.09.2026: https://cbd.minjust.gov.kg/7-58349/edition/59440/ru. Сверяйте взаимосвязанные тексты постановлений № 639 и № 385.',
    'UNDER_REVIEW',
    'legal-source-quality-review',
    'legal-source-quality-review',
    NOW(),
    NOW(),
    1
)
